import React, { useMemo, useState } from 'react';
import {
  CurrencyDollarIcon,
  BanknotesIcon,
  ArrowTrendingDownIcon,
  ArrowTrendingUpIcon,
  WalletIcon,
} from '@heroicons/react/24/outline';
import { ResponsiveContainer, AreaChart, Area, Tooltip } from 'recharts';
import { format } from 'date-fns';

/* --------------------------------------------------------
   CONFIG
--------------------------------------------------------- */

const ICONS = {
  funds: CurrencyDollarIcon,
  income: BanknotesIcon,
  expenses: ArrowTrendingDownIcon,
  budget: WalletIcon,
  // Use a distinct icon for balance so it reads visually different from Total Funds
  balance: WalletIcon,
};

const GRADIENTS = {
  // modern, vibrant yet soft pairs (primary stroke, secondary fill)
  funds: ['#6366f1', '#a5b4fc'],
  income: ['#10b981', '#86efac'],
  expenses: ['#f43f5e', '#fca5a5'],
  budget: ['#f59e0b', '#fcd34d'],
  // distinct cyan/teal for balance to differentiate from funds
  balance: ['#06b6d4', '#7dd3fc'],
};

const RING = {
  funds: 'ring-indigo-200/70',
  income: 'ring-emerald-200/70',
  expenses: 'ring-rose-200/70',
  budget: 'ring-amber-200/70',
  // cyan ring for balance
  balance: 'ring-cyan-200/70',
};

const ICON_BG = {
  // gradient tiles for a premium, modern feel
  funds: 'bg-gradient-to-br from-indigo-600 to-sky-500',
  income: 'bg-gradient-to-br from-emerald-600 to-teal-500',
  expenses: 'bg-gradient-to-br from-rose-600 to-orange-500',
  budget: 'bg-gradient-to-br from-amber-600 to-yellow-500',
  // distinct cyan/teal tile for balance
  balance: 'bg-gradient-to-br from-cyan-600 to-teal-500',
};

/* --------------------------------------------------------
   COMPONENT
--------------------------------------------------------- */

export default function StatCard({
  title,
  value,
  series = [],
  variant = 'funds',
  className = '',
}) {
  const Icon = ICONS[variant] || CurrencyDollarIcon;
  const gradientId = useMemo(() => `stat-grad-${variant}-${String(title)}`.replace(/[^a-z0-9-_]/gi, '-'), [variant, title]);
  const [primary, secondary] = GRADIENTS[variant] || ['#2563eb', '#bfdbfe'];

  // timeframe: W (7d), M (30d), Y (365d)
  const [range, setRange] = useState('W');
  const days = range === 'W' ? 7 : range === 'M' ? 30 : 365;

  // normalize incoming series keys to { value, label }
  const normalized = useMemo(() => {
    return (series || []).map((p) => ({
      value: Number(p.value ?? p.y ?? 0),
      label: p.date ?? p.x ?? null,
    }));
  }, [series]);

  const data = useMemo(() => {
    if (!normalized || normalized.length === 0) return [];
    if (normalized.length <= days) return normalized;
    return normalized.slice(-days);
  }, [normalized, days]);

  // simple % change over current range
  const pct = useMemo(() => {
    if (!data || data.length < 2) return 0;
    const a = Number(data[0]?.value ?? 0);
    const b = Number(data[data.length - 1]?.value ?? 0);
    return a ? ((b - a) / Math.abs(a)) * 100 : 0;
  }, [data]);

  const lastText = useMemo(() => {
    if (!data || data.length === 0) return '';
    const raw = data[data.length - 1]?.label;
    const d = raw ? new Date(raw) : new Date();
    if (isNaN(d)) return '';
    try {
      return format(d, 'MMM d, yyyy');
    } catch {
      return '';
    }
  }, [data]);

  const renderTooltip = useMemo(() => {
    return ({ active, payload }) => {
      if (!active || !payload || payload.length === 0) return null;
      const item = payload[0]?.payload || {};
      const dt = item.label ? new Date(item.label) : null;
      const dText = dt && !isNaN(dt) ? format(dt, 'MMM d, yyyy') : '';
      return (
        <div className="px-2 py-1 rounded-md bg-white/90 backdrop-blur ring-1 ring-slate-200 shadow text-[10px] text-slate-700 dark:bg-slate-800/90 dark:ring-slate-700 dark:text-slate-100">
          <div className="font-medium text-slate-900 dark:text-slate-100">{(item.value ?? 0).toLocaleString()}</div>
          {dText && <div className="text-slate-500 dark:text-slate-300">{dText}</div>}
        </div>
      );
    };
  }, []);

  return (
    <div
      className={`group relative overflow-hidden rounded-2xl bg-white/95 backdrop-blur-md ring-1 shadow hover:shadow-md transform hover:-translate-y-0.5 transition-all ${RING[variant]} ${className} dark:bg-slate-900/70 dark:ring-slate-800 dark:shadow-none`}
    >
      {/* background tint */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background: `linear-gradient(135deg, ${GRADIENTS[variant][0]}10, ${GRADIENTS[variant][1]})`,
        }}
      />

      <div className="relative p-4 sm:p-5 min-h-[132px] flex flex-col">
        
        {/* header */}
        <div className="flex items-center gap-4 min-w-0">
          <div
            className={`h-10 w-10 flex items-center justify-center rounded-xl text-white shadow ${ICON_BG[variant]}`}
          >
            <Icon className="h-5 w-5 opacity-90" />
          </div>

          <div className="min-w-0">
            <p className="text-xs uppercase tracking-wide text-slate-500 truncate dark:text-slate-400">
              {title}
            </p>
            <p
              className="mt-1 font-semibold text-slate-900 whitespace-nowrap overflow-hidden text-ellipsis text-[clamp(0.95rem,2.2vw,1.55rem)] dark:text-slate-100"
              title={String(value)}
            >
              {value}
            </p>
          </div>
        </div>

        {/* spark-line */}
        {data.length > 0 && (
          <div className="mt-2 h-12 sm:h-16">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={data}>
                <defs>
                  <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={primary} stopOpacity={0.22} />
                    <stop offset="100%" stopColor={secondary} stopOpacity={0.04} />
                  </linearGradient>
                </defs>
                <Tooltip content={renderTooltip} cursor={{ stroke: primary, strokeWidth: 1, strokeOpacity: 0.15 }} />
                <Area
                  type="monotone"
                  dataKey="value"
                  stroke={primary}
                  fill={`url(#${gradientId})`}
                  strokeWidth={1.5}
                  strokeOpacity={0.85}
                  fillOpacity={1}
                  strokeLinejoin="round"
                  strokeLinecap="round"
                  dot={false}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* percent change badge */}
        {data.length > 1 && (
          <span
            className={`absolute top-2 right-3 rounded-full px-2 py-0.5 text-xs font-medium inline-flex items-center gap-1 ${
              pct >= 0
                ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300'
                : 'bg-rose-50 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300'
            }`}
          >
            {pct >= 0 ? (
              <ArrowTrendingUpIcon className="h-3.5 w-3.5" />
            ) : (
              <ArrowTrendingDownIcon className="h-3.5 w-3.5" />
            )}
            {Math.abs(pct).toFixed(1)}%
          </span>
        )}

        {/* footer: timestamp + timeframe chips */}
        <div className="mt-2 text-[11px] text-slate-500 flex items-center justify-between dark:text-slate-400">
          <span className="truncate">{lastText ? `as of ${lastText}` : ''}</span>
          <div className="inline-flex items-center rounded-full bg-slate-100 p-0.5 shadow-inner dark:bg-slate-800/60">
            {['W','M','Y'].map((r) => (
              <button
                key={r}
                onClick={() => setRange(r)}
                className={`px-2 py-0.5 text-[10px] sm:text-xs rounded-full transition-colors ${range===r ? 'bg-white text-slate-900 shadow dark:bg-slate-700 dark:text-slate-100' : 'text-slate-600 hover:text-slate-800 dark:text-slate-300 dark:hover:text-slate-100'}`}
                aria-label={`Show ${r==='W'?'7d':r==='M'?'30d':'365d'}`}
              >
                {r}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
