import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { doc, getDoc, updateDoc, addDoc, collection, deleteDoc, setDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card';

export default function AcceptInvite() {
  const { orgId, token } = useParams();
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [invite, setInvite] = useState(null);
  const [orgName, setOrgName] = useState('');
  const [accepted, setAccepted] = useState(false);
  const [resolvedOrgId, setResolvedOrgId] = useState(orgId);
  const friendlyRole = (r) => (r === 'financial_officer' || r === 'finance') ? 'Finance' : (r === 'admin' ? 'Admin' : 'Viewer');

  const looksLikeEmail = (s) => typeof s === 'string' && s.includes('@');
  const looksLikeId = (s) => typeof s === 'string' && /^[A-Za-z0-9_-]{8,}$/.test(s) && s.length > 8;
  const safeOrgName = (name, fallback) => {
    if (name && typeof name === 'string' && !looksLikeEmail(name) && !looksLikeId(name) && name.trim().length) return name;
    if (fallback && typeof fallback === 'string' && !looksLikeEmail(fallback) && !looksLikeId(fallback) && fallback.trim().length) return fallback;
    return 'Organization';
  };

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        // Try reading a top-level invite doc by token first
        let orgRefId = orgId;
        try {
          const topInviteRef = doc(db, 'invites', token);
          const topInviteSnap = await getDoc(topInviteRef);
          if (topInviteSnap.exists()) {
            const topData = topInviteSnap.data();
            orgRefId = topData.orgId || orgRefId;
            setResolvedOrgId(orgRefId);
          }
        } catch (e) {
          // ignore top-level invite read errors and fallback to org document
        }

        const ref = doc(db, 'orgs', orgRefId);
        const snap = await getDoc(ref);
        if (!snap.exists()) {
          // If org doc is missing but top-level invite exists, still show invite details
          try {
            const topInviteRef = doc(db, 'invites', token);
            const topInviteSnap = await getDoc(topInviteRef);
            if (topInviteSnap.exists()) {
              const topData = topInviteSnap.data();
              setOrgName(safeOrgName(topData?.organization, orgRefId));
              setInvite(topData);
              setLoading(false);
              return;
            }
          } catch {}
          setError('Organization not found');
          setLoading(false);
          return;
        }
        const data = snap.data();
        setOrgName(safeOrgName(data?.name, orgRefId));
        const invs = Array.isArray(data.invites) ? data.invites : [];
        const found = invs.find((i) => i.token === token) || null;
        if (!found) {
          // Fall back to top-level invite if not present in org doc
          try {
            const topInviteRef = doc(db, 'invites', token);
            const topInviteSnap = await getDoc(topInviteRef);
            if (topInviteSnap.exists()) {
              const topData = topInviteSnap.data();
              setInvite(topData);
              setLoading(false);
              return;
            }
          } catch {}
          setError('Invalid or expired invite link');
          setLoading(false);
          return;
        }
        setInvite(found);
      } catch (e) {
        // Friendly handling for permission errors: if unauthenticated, prompt to sign in
        const msg = (e?.code === 'permission-denied' || (e?.message || '').toLowerCase().includes('permission'))
          ? 'Please sign in with the invited email to view and accept this invite.'
          : e?.message || 'Failed to load invite';
        setError(msg);
      } finally {
        setLoading(false);
      }
    })();
  }, [orgId, token, user]);

  const accept = async () => {
    if (!user) {
      // For unauthenticated users, the create account button is already shown above
      return;
    }

    // Ensure the signed-in user matches the invited email
    if (invite?.email && user.email && invite.email.toLowerCase() !== user.email.toLowerCase()) {
      setError('You must be signed in as the invited email to accept this invitation. Please sign out and sign in with the invited email.');
      return;
    }

    try {
      setLoading(true);
      const ref = doc(db, 'orgs', resolvedOrgId);
      let snap = await getDoc(ref);
      let data = snap.exists() ? (snap.data() || {}) : {};
      // If org doc doesn't exist, create a minimal one so the invite can be accepted
      if (!snap.exists()) {
        const base = {
        name: safeOrgName(invite?.organization, resolvedOrgId),
          createdAt: new Date().toISOString(),
          members: [],
          memberships: [],
          invites: invite ? [invite] : [],
        };
        await setDoc(ref, base);
        snap = await getDoc(ref);
        data = snap.exists() ? (snap.data() || {}) : base;
      }
      const invs = Array.isArray(data.invites) ? data.invites : [];
      const inv = invs.find((i) => i.token === token) || invite;
      if (!inv) throw new Error('Invalid or expired invite');
      const memberships = Array.isArray(data.memberships) ? data.memberships : [];
      const already = memberships.some((m) => m.userId === user.id);

      const roleNormalized = (inv.role === 'finance') ? 'financial_officer' : (inv.role || 'viewer');
      const newMembership = { userId: user.id, email: user.email || '', role: roleNormalized, addedAt: new Date().toISOString() };

      const nextMemberships = already
        ? memberships.map((m) => (m.userId === user.id ? { ...m, role: roleNormalized || m.role } : m))
        : [...memberships, newMembership];
      const nextMembers = Array.isArray(data.members) ? (already ? data.members : Array.from(new Set([...(data.members || []), user.id]))) : [user.id];
      const nextInvites = invs.filter((i) => i.token !== token);

      // create or update funder entry for this user so they have a portal
      try {
        const funderObj = {
          id: user?.id || `funder-${Date.now()}`,
          name: invite?.name || user?.displayName || (user?.email || '').split('@')[0] || 'Funder',
          email: user?.email || invite?.email || '',
          status: 'active',
          createdAt: new Date().toISOString(),
        };

        const existingFunders = Array.isArray(data.funders) ? data.funders : [];
        const nextFunders = [
          // keep other funders but replace any existing with same id
          ...existingFunders.filter((f) => f && f.id !== funderObj.id),
          funderObj,
        ];

        await updateDoc(ref, {
          memberships: nextMemberships,
          members: nextMembers,
          invites: nextInvites,
          funders: nextFunders,
        });

        // Also remove top-level invite doc if present
        try { await deleteDoc(doc(db, 'invites', token)); } catch (e) { /* non-fatal */ }

        // send confirmation email with direct portal link (if mail trigger configured)
        try {
          const portalLink = `${window.location.origin}/app/funders/portal/${funderObj.id}`;
          const subject = `${orgName}: your funder portal is ready`;
          const mail = {
            to: [funderObj.email || invite?.email].filter(Boolean),
            message: {
              subject,
              text: `Your funder portal is ready. Open: ${portalLink}`,
              html: `<div style="font-family: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
                <h3 style="color:#0f172a">Welcome to ${orgName}</h3>
                <p>Your funder portal has been created. Click the button below to open your portal and view contributions, projects, and invoices.</p>
                <p style="margin:18px 0"><a href="${portalLink}" style="background:#0ea5e9;color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;">Open your funder portal</a></p>
                <p style="font-size:13px;color:#6b7280">If the button doesn't work, copy and paste this link into your browser: <br/><a href="${portalLink}" style="color:#0ea5e9">${portalLink}</a></p>
              </div>`,
            },
          };
          if ((mail.to || []).length) {
            await addDoc(collection(db, 'mail'), mail);
          }
        } catch (mailErr) {
          console.warn('Failed to enqueue funder portal email', mailErr);
        }

        // redirect funder to their portal
        setAccepted(true);
        setTimeout(() => navigate(`/app/funders/portal/${funderObj.id}`), 800);
        return;
      } catch (e) {
        // If creating funder fails, still proceed with memberships update and redirect to dashboard
        try {
          await updateDoc(ref, {
            memberships: nextMemberships,
            members: nextMembers,
            invites: nextInvites,
          });
          try { await deleteDoc(doc(db, 'invites', token)); } catch (e2) { /* non-fatal */ }
        } catch (e2) {
          console.error('Failed to finalize invite acceptance', e2);
        }

        setAccepted(true);
        setTimeout(() => navigate('/app/dashboard/overview'), 1200);
        return;
      }
    } catch (e) {
      setError(e?.message || 'Failed to accept invite');
    } finally {
      setLoading(false);
    }
  };

  const handleSignOut = async () => {
    try {
      await logout();
      // After sign out redirect to register so they can sign in with invited email
      navigate(`/register?orgId=${orgId}&token=${token}${invite?.email ? `&email=${encodeURIComponent(invite.email)}` : ''}${invite?.name ? `&name=${encodeURIComponent(invite.name)}` : ''}&redirect=${encodeURIComponent('/app/funders/portal/me')}`);
    } catch (e) {
      setError('Failed to sign out.');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold leading-7 text-gray-900 sm:truncate sm:text-3xl sm:tracking-tight dark:text-slate-100">Accept invitation</h2>
          <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">Join the organization and start collaborating.</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Invitation details</CardTitle>
        </CardHeader>
        <CardContent>
          {loading && <div className="text-sm text-slate-600">Loading…</div>}
          {!loading && error && <div className="text-sm text-rose-600">{error}</div>}
          {!loading && !error && (
            invite ? (
            <div className="space-y-3">
              <div className="text-sm text-slate-700 dark:text-slate-200">You're invited to join <span className="font-medium">{orgName}</span> as <span className="font-semibold">{friendlyRole(invite.role)}</span>.</div>
              {!user && (
                <div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200 dark:bg-slate-900 dark:border-slate-700">
                  <h3 className="text-xl font-semibold">You're invited to join {orgName || 'this organization'}</h3>
                  <p className="mt-2 text-sm text-slate-600 dark:text-slate-300">Create an account with the invited email to accept this invitation. You will be added to the existing organization and won't need to complete the organization setup.</p>
                  {invite?.email && (
                    <div className="mt-3 text-sm">Invited email: <strong>{invite.email}</strong></div>
                  )}
                  <div className="mt-4 flex flex-wrap gap-3">
                    <Link to={`/register?orgId=${orgId}&token=${token}${invite?.email ? `&email=${encodeURIComponent(invite.email)}` : ''}${invite?.name ? `&name=${encodeURIComponent(invite.name)}` : ''}&redirect=${encodeURIComponent(`/invite/${orgId}/${token}`)}`} className="inline-block px-4 py-2 bg-sky-600 text-white rounded-md">Create account</Link>
                    <Link to={`/login?redirect=${encodeURIComponent(`/invite/${orgId}/${token}`)}`} className="inline-block px-4 py-2 bg-slate-100 rounded-md">Already have an account? Sign in</Link>
                    <button onClick={() => { navigator.clipboard?.writeText(window.location.href); }} className="inline-block px-3 py-2 bg-slate-50 border rounded-md">Copy link</button>
                  </div>
                  <div className="mt-3 text-xs text-slate-500">If this invite was unexpected, contact the inviter or ignore this email.</div>
                </div>
              )}

              {user && invite?.email && user.email && invite.email.toLowerCase() !== user.email.toLowerCase() && (
                <div className="space-y-2">
                  <div className="text-sm text-slate-600">You're signed in as <strong>{user.email}</strong>, but this invite was sent to <strong>{invite.email}</strong>.</div>
                  <div className="flex gap-2">
                    <button onClick={handleSignOut} className="px-4 py-2 rounded-md bg-rose-600 hover:bg-rose-700 text-white text-sm shadow-sm">Sign out and sign in as invited user</button>
                    <Link to="/login" className="px-4 py-2 rounded-md bg-slate-100 hover:bg-slate-200 text-sm">Switch account</Link>
                  </div>
                </div>
              )}

              {user && (!invite?.email || invite.email.toLowerCase() === (user.email || '').toLowerCase()) && !accepted && (
                <button onClick={accept} className="px-4 py-2 rounded-md bg-sky-700 hover:bg-sky-800 text-white text-sm shadow-sm">Accept invite</button>
              )}

              {accepted && (
                <div className="text-sm text-emerald-700">Invitation accepted! Redirecting…</div>
              )}
            </div>
            ) : (
              <div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200 dark:bg-slate-900 dark:border-slate-700">
                <h3 className="text-xl font-semibold">Invitation</h3>
                <p className="mt-2 text-sm text-slate-600 dark:text-slate-300">We could not load the full invite details, but you can still create an account or sign in to accept your invitation.</p>
                <div className="mt-4 flex flex-wrap gap-3">
                  <Link to={`/register?orgId=${orgId}&token=${token}&redirect=${encodeURIComponent(`/invite/${orgId}/${token}`)}`} className="inline-block px-4 py-2 bg-sky-600 text-white rounded-md">Create account</Link>
                  <Link to={`/login?redirect=${encodeURIComponent(`/invite/${orgId}/${token}`)}`} className="inline-block px-4 py-2 bg-slate-100 rounded-md">Already have an account? Sign in</Link>
                  <button onClick={() => { navigator.clipboard?.writeText(window.location.href); }} className="inline-block px-3 py-2 bg-slate-50 border rounded-md">Copy link</button>
                </div>
              </div>
            )
          )}
        </CardContent>
      </Card>
    </div>
  );
}
